  product *= m % 10;
  m = Math.floor(m / 10);
}

console.log(`Digit product: ${product}`);

steps.body:
`do { ... } while (condition);` runs the body first and checks the condition after. The body always runs at least once. Note the semicolon after the condition. A `const` or `let` declared inside the braces is not visible in the condition, so declare what the condition checks before `do`.

That fixes a digit loop bug: `while (n > 0)` counts 0 as having zero digits, because the condition is false right away. A `do...while` counts it once.

```javascript
let n = 0;
let digits = 0;
do {
  digits++;
  n = Math.floor(n / 10);
} while (n > 0);
// digits is 1
```

Sometimes the right place to stop is in the middle of the body, after you compute something. Write `while (true)` and leave with `break` when you are done. Code after the `break` check only runs on passes that keep going:

```javascript
let total = 0;
while (true) {
  total += 7;
  if (total > 30) {
    break;
  }
  console.log(total);
}
// prints 7, 14, 21, 28 and stops at 35
```

A `while (true)` loop must reach a `break` on some path, or it runs forever.

example.code:
const first = 0;
let n = first;
let digits = 0;
do {
  digits++;
  n = Math.floor(n / 10);
} while (n > 0);
console.log(`${first} has ${digits} ${digits === 1 ? "digit" : "digits"}`);

const second = 512;
n = second;
digits = 0;
do {
  digits++;
  n = Math.floor(n / 10);
} while (n > 0);
console.log(`${second} has ${digits} ${digits === 1 ? "digit" : "digits"}`);

let power = 1;
while (true) {
  power *= 3;
  if (power > 500) {
    break;
  }
}
console.log(`First power of 3 above 500: ${power}`);

